import { fail } from '@sveltejs/kit';
import { read_contact, validate_contact } from '#lib/contact.ts';
import type { Actions } from './$types';

export const actions: Actions = {
	default: async ({ request }) => {
		const values = read_contact(await request.formData());
		const errors = validate_contact(values);

		if (Object.keys(errors).length > 0) {
			return fail(400, { values, errors });
		}

		// Nothing is stored: the message is only acknowledged.
		return { success: true as const, name: values.name };
	}
};
