cat > src/routes/contact/+page.svelte <<'EOF'
<script lang="ts">
	import { enhance } from '$app/forms';
	import {
		read_contact,
		validate_contact,
		type ContactErrors,
		type ContactValues
	} from '#lib/contact.ts';
	import type { PageProps, SubmitFunction } from './$types';

	let { form }: PageProps = $props();

	// Errors found in the browser, before anything is sent.
	let client_errors = $state<ContactErrors | null>(null);

	let errors: ContactErrors = $derived(
		client_errors ?? (form && 'errors' in form ? form.errors : {}) ?? {}
	);
	let values: Partial<ContactValues> = $derived(form && 'values' in form ? form.values : {});
	let sent_name = $derived(
		!client_errors && form && 'success' in form && form.success ? form.name : null
	);

	const submit: SubmitFunction = ({ formData, cancel }) => {
		const found = validate_contact(read_contact(formData));
		if (Object.keys(found).length > 0) {
			client_errors = found;
			cancel();
			return;
		}
		client_errors = null;
	};
</script>

<svelte:head>
	<title>Contact | Bookshelf</title>
</svelte:head>

<h1>Contact</h1>

{#if sent_name !== null}
	<p class="success" role="status">Thanks, {sent_name}! Your message has been sent.</p>
{/if}

<form method="POST" novalidate use:enhance={submit}>
	<div class="field">
		<label for="name">Name</label>
		<input
			id="name"
			name="name"
			type="text"
			value={values.name ?? ''}
			aria-invalid={errors.name ? 'true' : undefined}
			aria-describedby={errors.name ? 'name-error' : undefined}
		/>
		{#if errors.name}
			<p class="error" id="name-error">{errors.name}</p>
		{/if}
	</div>

	<div class="field">
		<label for="email">Email</label>
		<input
			id="email"
			name="email"
			type="email"
			value={values.email ?? ''}
			aria-invalid={errors.email ? 'true' : undefined}
			aria-describedby={errors.email ? 'email-error' : undefined}
		/>
		{#if errors.email}
			<p class="error" id="email-error">{errors.email}</p>
		{/if}
	</div>

	<div class="field">
		<label for="message">Message</label>
		<textarea
			id="message"
			name="message"
			rows="5"
			value={values.message ?? ''}
			aria-invalid={errors.message ? 'true' : undefined}
			aria-describedby={errors.message ? 'message-error' : undefined}
		></textarea>
		{#if errors.message}
			<p class="error" id="message-error">{errors.message}</p>
		{/if}
	</div>

	<button type="submit">Send</button>
</form>

<style>
	.field {
		display: flex;
		flex-direction: column;
		gap: 0.25rem;
		margin-bottom: 1rem;
	}

	input,
	textarea {
		font: inherit;
		padding: 0.4rem;
	}

	.error {
		margin: 0;
		color: #b00020;
	}

	.success {
		color: #1b5e20;
	}
</style>
